import { useContext, useMemo } from 'react';
import { RendererContext } from '../../rendererConnect/RendererContext.js';
export function useCosmosNotification() {
    const rendererContext = useContext(RendererContext);
    const { rendererId, rendererConnect, selectedFixture } = rendererContext;
    if (!selectedFixture) {
        throw new Error('useCosmosNotification can only be used inside a Cosmos fixture');
    }
    const { fixtureId } = selectedFixture;
    const { postMessage } = rendererConnect;
    return useMemo(() => ({
        pushSticky: (notification) => {
            postMessage({
                type: 'pushStickyNotification',
                payload: {
                    rendererId,
                    fixtureId,
                    notification,
                },
            });
        },
        removeSticky: (notificationId) => {
            postMessage({
                type: 'removeStickyNotification',
                payload: {
                    rendererId,
                    fixtureId,
                    notificationId,
                },
            });
        },
        pushTimed: (notification) => {
            postMessage({
                type: 'pushTimedNotification',
                payload: {
                    rendererId,
                    fixtureId,
                    notification,
                },
            });
        },
    }), [fixtureId, postMessage, rendererId]);
}
